//! The schema-definition → generated-type table the protocol crate's schema
//! tests read (`tests/registry/<revision>.rs`). With it, a test can decode an
//! instance of every definition into its Rust type without a hand-kept list
//! that a schema update would silently outgrow.

use std::fmt::Write as _;

use crate::names::{generated_types, rust_name};

/// One `registry!` invocation listing `"Definition" => Type` for every
/// definition typify generated a type for. `src` is the generated file.
pub fn render(defs: &[String], src: &str, label: &str) -> String {
    let types = generated_types(src);
    let mut out = format!(
        "// @generated by turbomcp-codegen from {label}. DO NOT EDIT.\n\
         //\n\
         // Every schema definition and the generated type that holds it, for the\n\
         // schema tests. The includer defines `registry!`.\n\
         registry! {{\n"
    );
    for def in defs {
        if let Some(ty) = rust_name(def, &types) {
            writeln!(out, "    {def:?} => {ty},").expect("writing to a String");
        }
    }
    out.push_str("}\n");
    out
}
